// https://coolors.co/palette/03071e-370617-6a040f-9d0208-d00000-dc2f02-e85d04-f48c06-faa307-ffba08
let CLRS = ("03071e-370617-6a040f-9d0208-d00000-dc2f02-e85d04-f48c06-faa307-ffba08").split("-");
let startFrame;

function setup() {
	createCanvas(windowWidth, windowHeight);
	describe("outline of a row of circles in an unordered color range from yellow>red>black ");
	background("beige");

	CLRS = shuffle(CLRS);
	frameRate(15);
	startFrame = frameCount || 0;
}

function draw() {
	const repeatEveryNthCircles = 4;
	const num = CLRS.length;
	const _d_w = (width / (num / repeatEveryNthCircles + 1)) * 1; // max(width, height) / num * repeatEveryNthCircles * 1.5;
	const _d_h = height * 0.7;
	const d = ~~min(_d_w, _d_h);
	const sw = d/repeatEveryNthCircles; // d/(repeatEveryNthCircles+1)
	strokeWeight(sw);
	noFill();

	const i = frameCount - startFrame;
	if (i === num) {
		// noLoop() removed for animation
		return;
	}
	// for (let i = 0; i < num; i++) {
		const clr = color("#"+CLRS[i]+"F0");
		stroke(clr)
		// circle(d + i * d / 4, height - d * 1.2, d)
		// circleOfPoints(width/2 - num/repeatEveryNthCircles/2 * d + i * d/repeatEveryNthCircles, height - d/2 -sw, d-sw, d+sw, clr, pow(d, 1.8))
		circleOfArcs(width/2 - num/repeatEveryNthCircles/2 * d + i * d/repeatEveryNthCircles, height - d/2 -sw, d-sw, d+sw, clr, sw); // pow(d, 0.75)
	// }
}

function circleOfPoints(x, y, d1, d2, clr, num, debug = false) {
	push();

	if (debug)  {		
		stroke(32, 64);
		strokeWeight(1);
		noFill();
		circle(x, y, d1);
		circle(x, y, d2);
	}

	// stroke(clr);
	const dev = 12;
	const clrRed = red(window.color(clr));
	const clrGreen = green(window.color(clr));
	const clrBlue = blue(window.color(clr));
	const clrAlpha = alpha(window.color(clr));
	for (let i = 0; i < num; i++) {
		stroke(
			constrain(clrRed + random(-dev, dev), 0, 255),
			constrain(clrGreen + random(-dev, dev), 0, 255),
			constrain(clrBlue + random(-dev, dev), 0, 255),
			clrAlpha
		);
		strokeWeight(random(0.5, 3.3));
		const a = random(TWO_PI);
		const r = random(d1, d2) / 2;
		const xo = cos(a) * r;
		const yo = sin(a) * r;
		point(x + xo, y + yo);
	}

	pop();
}

function circleOfArcs(x, y, d1, d2, clr, num, debug = false) {
	push();

	if (debug)  {		
		stroke(32, 64);
		strokeWeight(1);
		noFill();
		circle(x, y, d1);
		circle(x, y, d2);
	}

	// stroke(clr);
	var dev = 12;
	var clrRed = red(window.color(clr));
	var clrGreen = green(window.color(clr));
	var clrBlue = blue(window.color(clr));
	var clrAlpha = alpha(window.color(clr));
	for (let i = 0; i < num; i++) {
		stroke(
			constrain(clrRed + random(-dev, dev), 0, 255),
			constrain(clrGreen + random(-dev, dev), 0, 255),
			constrain(clrBlue + random(-dev, dev), 0, 255),
			clrAlpha
		);
		strokeWeight(random(0.5, 4.3));
		const a1 = PI-random(PI); // random(TWO_PI);
		const a2 = PI+random(PI); // random(TWO_PI);
		var d = random(d1, d2);
		arc(x, y, d, d, a1, a2);
	}

	pop();
}

function mouseReleased() {
	loop();
	setup();
}
